"use strict";(self.webpackChunk=self.webpackChunk||[]).push([[5885],{25885:function(e){e.exports=JSON.parse('[{"chapterId":1,"tracks":[{"id":"foundation-anchor","title":"Tawheed Anchor","description":"Let Allah\'s oneness steady your pace by repeating one clear truth from the foundation overview.","steps":["Highlight a sentence from the chapter that feels like a promise about Tawheed.","Turn that sentence into a short dua and recite it after your next prayer.","Notice how the dua reshaped a decision before the day ends."]},{"id":"foundation-story","title":"Foundation Story","description":"Tell the new insight to someone you trust so the lesson stays alive in conversation.","steps":["Share what moved you about today\'s foundation oneness with a family member or friend.","Ask how that idea fits into their day-to-day choices.","Jot down one unexpected reply to revisit later."]},{"id":"foundation-quiet","title":"Quiet Commitments","description":"Lock a tiny habit to honor the foundation, then track how it softens your mind.","steps":["Pick one gentle habit (a prayer reminder, a breath, a dua) rooted in Tawheed.","Schedule it with a note before bedtime.","Reflect on whether the habit felt like worship or just routine."]}]},{"chapterId":2,"tracks":[{"id":"belief-breath","title":"Belief Breaths","description":"Carry one article of faith through the day with steady breathing and calm notes.","steps":["Choose an article of faith and whisper it at dawn.","Name how that belief guided a midday choice.","Close the night asking which article needs more gentle trust."]},{"id":"belief-angel","title":"Angel Notes","description":"Let angelic reminders color your schedule with gratitude and awe.","steps":["List two angelic attributes that inspired you while reading the chapter.","Send a quick note or text naming the one you need most today.","Offer that attribute back in dua before sleep."]},{"id":"belief-qadar","title":"Qadar Check","description":"Settle around divine decree and how it steadies your next step.","steps":["Recall a recent worry and pair it with trust in Qadar.","Write a short dua for patience.","Replay that dua during the next moment of uncertainty."]}]},{"chapterId":3,"tracks":[{"id":"pillar-pulse","title":"Pillar Pulse","description":"Rotate through a pillar, let its rhythm anchor the day, and celebrate each small win.","steps":["Pick one of the Five Pillars and name what the pillar asks of you today.","Deliver a small action (prayer, charity, remembrance) tied to that pillar.","Log how the action shifted your heart or focus."]},{"id":"pillar-map","title":"Ritual Mapping","description":"Draw a mini checklist that strings the pillars into gentle checkpoints.","steps":["Write one thing each pillar invites you to notice this week.","Share the checklist with a study partner or family member.","Mark one moment when the pillar felt close enough to touch."]},{"id":"pillar-ripple","title":"Community Ripple","description":"Let the pillars reach someone else by inviting them into your reflection.","steps":["Tell a friend which pillar keeps surfacing in your mind.","Ask how they live that pillar when life gets loud.","Collect one observation you can repeat as a dua."]}]},{"chapterId":4,"tracks":[{"id":"quran-echo","title":"Quran Echo","description":"Select a verse that lingers, reflect on it, and let it lead a dua.","steps":["Pick a verse from today\'s chapter that feels like a personal message.","Write a brief reflection about why it resonates now.","Turn that reflection into a dua before your next prayer."]},{"id":"quran-tafsir","title":"Tafsir Window","description":"Open a tafsir note, explain it aloud, and watch the meaning settle.","steps":["Read a tafsir snippet linked to the chapter.","Explain the main idea out loud, even if just to yourself.","Notice what emotion the insight unlocks and jot it down."]},{"id":"quran-rhythm","title":"Recitation Rhythm","description":"Plan a short recitation loop to keep the Quran close for the next few days.","steps":["Set a tiny recitation goal (a verse, a line) and lock it into your routine.","Pair the recitation with calm breathing or a walk.","Note one moment the verse spoke to your day."]}]},{"chapterId":5,"tracks":[{"id":"prophetic-pause","title":"Prophetic Pause","description":"Borrow a Prophetic trait and let it frame a live intention.","steps":["Choose one Prophetic characteristic that calls to you today.","Set a clear intention using that trait for the next interaction.","Record whether the trait softened your tone or choices."]},{"id":"prophetic-story","title":"Companion Story","description":"Tell a companion story that mirrors your own season.","steps":["Pick a story from the chapter that echoes your experience.","Share it with someone who can relate, even briefly.","Ask how the story nudged their own kindness."]},{"id":"prophetic-mercies","title":"Mercy Ledger","description":"Track three merciful moments and thank Allah for each one.","steps":["Notice two moments you offered mercy without being asked.","Write them down with a short gratitude note.","Close with a quick dua asking to keep the mercy flowing."]}]},{"chapterId":6,"tracks":[{"id":"prayer-rhythm","title":"Prayer Rhythm","description":"Let Salah become a mindful pause with words, breaths, and gratitude.","steps":["Before Fajr or Dhuhr, name the feeling you want Salah to steady.","Pray with that intention and breathe through each rukūʿ.","During the next prayer, quietly note how the intention landed."]},{"id":"prayer-wudu","title":"Wudu Pause","description":"Use wudu to reset the body and invite calm into prayer.","steps":["Mindfully go through wudu, naming the limbs as you clean them.","Lift a short dua while the water runs.","Feel how the ritual preps you before the salah that follows."]},{"id":"prayer-evening","title":"Evening Reflection","description":"Let gratitude after Isha remind you why the prayers keep you grounded.","steps":["After Isha, list one blessing each prayer unlocked this week.","Speak a quiet dua for steady focus tomorrow.","Tie the reflection to one habit you\'ll keep."]}]},{"chapterId":7,"tracks":[{"id":"dhikr-flow","title":"Dhikr Flow","description":"Anchor a string of remembrance across short pauses.","steps":["Choose three short dhikr phrases (SubhanAllah, Alhamdulillah, Allahu Akbar).","Repeat them during three mini-breaks today.","Note how the repetitions eased your pace."]},{"id":"supplication-loop","title":"Supplication Loop","description":"Circle through duas you love and keep one close all week.","steps":["Pick a dua from the chapter to guard your tongue today.","Share its meaning with someone in a short voice note.","Replay the note when you need calm."]},{"id":"reminder-thread","title":"Reminder Thread","description":"Link a reminder to a real take-away so remembrance becomes habitual.","steps":["Set a phone or smartwatch reminder with a dua phrase.","When it rings, pause and breathe the dua aloud.","Write one quick line about the shifted feeling."]}]},{"chapterId":8,"tracks":[{"id":"heart-reset","title":"Heart Reset","description":"Name the emotion tugging at you and pair it with a softer choice.","steps":["Identify the feeling occupying your heart right now.","Choose a small kindness that gently counters it.","Observe how the kindness reshapes the original feeling."]},{"id":"heart-truth","title":"Truth Check","description":"Measure actions against sincerity and re-align with honesty.","steps":["Ask: did my words match my inner state today?","Note one moment honesty felt hard but right.","Pray for the courage to keep that honesty alive."]},{"id":"heart-mercy","title":"Mercy Action","description":"Plan a mercy-based move that keeps your heart soft for others.","steps":["Choose someone who might benefit from a gentle check-in.","Send a quick dua or text rooted in empathy.","Journal how the exchange made your heart feel."]}]},{"chapterId":9,"tracks":[{"id":"manners-greet","title":"Adab Greeting","description":"Make one greeting an act of kindness rather than habit.","steps":["Plan a greeting that feels sincere for today\'s encounters.","Deliver it slowly, letting eye contact and tone match.","Record how the receiver responded did it warm the room?"]},{"id":"manners-listen","title":"Listening Altar","description":"Practice full presence so polite speech becomes active listening.","steps":["Give someone a full minute without interrupting.","Note the pauses, tones, and what stayed in your mind.","Offer a dua for patience before your next conversation."]},{"id":"manners-share","title":"Sharing Light","description":"Pass along a small kindness to reflect the chapter\'s etiquette lessons.","steps":["Share a compliment or helpful act with a neighbor or colleague.","Say a dua for their ease while doing it.","Write one observation about how the gesture shifted the energy."]}]},{"chapterId":10,"tracks":[{"id":"lifestyle-halal","title":"Halal Compass","description":"Frame one halal choice (eating, spending, resting) and guard it with intention.","steps":["Pick a habit tied to halal living and clarify why it matters.","Pause before the choice and whisper a short dua for guidance.","Share the decision with a trusted person to keep it anchored."]},{"id":"lifestyle-meals","title":"Intent Meals","description":"Turn a meal into a mindful celebration of gratitude.","steps":["Plan a meal with halal ingredients and invite reflection.","While eating, name two grateful thoughts aloud or inside your heart.","Take a tiny pause after the meal to say a simple dua of thanks."]},{"id":"lifestyle-boundary","title":"Boundary Reset","description":"Recalibrate rest and work with Allah-conscious boundaries.","steps":["List one boundary you want to protect this week (sleep, screen time, space).","Attach it to a short dua asking for steadiness.","Notice whether keeping the boundary brought peace."]}]},{"chapterId":11,"tracks":[{"id":"family-pause","title":"Family Pause","description":"Invite a circle member into a meaningful check-in.","steps":["Set aside five minutes to ask a loved one about their day.","Listen fully without problem-solving.","Reflect later on what you learned about their hopes."]},{"id":"family-marriage","title":"Marriage Insight","description":"Plan one gentle conversation about future goals or dreams.","steps":["Share a future goal or dua with your spouse or close partner.","Invite them to add their voice without judgment.","Journal the calm moments you noticed during the talk."]},{"id":"family-home","title":"Home Ritual","description":"Create a short ritual (meal, dua, gratitude) that keeps the home grounded.","steps":["Pick a time for a brief ritual someone else in the home can join.","Lead the ritual with a dua or remembrance.","Note how the ritual shaped the atmosphere afterward."]}]},{"chapterId":12,"tracks":[{"id":"community-ummah","title":"Ummah Reach","description":"Bridge kindness to someone in your community with practical care.","steps":["Choose a neighbor or fellow believer who might welcome support.","Send a short message or drop off a small kindness.","Dua for their ease and notice the warmth the action stirred."]},{"id":"community-care","title":"Care Call","description":"Call or message a person in need of encouragement from today\'s theme.","steps":["Make a quick call sharing a verse or dua that inspires you.","Ask if there\'s a specific way you can keep them in mind.","Write their request and repeat a dua for it tonight."]},{"id":"community-sadaqah","title":"Sadaqah Ripple","description":"Plan a micro-sadaqah that invites others to join later.","steps":["Map a small act of charity you can do (drop off food, volunteer).","Invite a friend or family member to join you.","Record what surprised you about the shared action."]}]},{"chapterId":13,"tracks":[{"id":"future-map","title":"Future Mapping","description":"Sketch a simple roadmap with dua markers for the next steps you can take.","steps":["Draft three small future goals tied to the lesson.","Pair each goal with a short dua for guidance.","Share one goal with a mentor or trusted friend."]},{"id":"future-vision","title":"Vision Partners","description":"Speak your vision aloud so accountability keeps it moving.","steps":["Tell someone about what you hope to build in the months ahead.","Ask for one practical suggestion they can offer.","Return to the vision with dua once a week."]},{"id":"future-account","title":"Accountability Dua","description":"Pair your roadmap with a dua that asks for resilience.","steps":["Write a dua for clarity, resilience, and right timing.","Repeat it each morning as you review the roadmap.","Note one place the dua softened your worry."]}]},{"chapterId":14,"tracks":[{"id":"hereafter-horizon","title":"Hereafter Horizon","description":"Let eternity be the horizon you keep returning to.","steps":["Imagine your legacy ten years from now and sketch a hopeful scene.","Tie each element to a deed you can do today.","Say a dua for steadfastness in that direction."]},{"id":"hereafter-legacy","title":"Legacy Notes","description":"Log three deeds that feel like seeds for the next life.","steps":["List three actions you can offer as ongoing charity or kindness.","Pray that Allah accepts them and keeps you humble.","Plan a small reminder so you revisit the list weekly."]},{"id":"hereafter-hope","title":"Hopeful Check","description":"Let hope and fear balance each other before major decisions.","steps":["Before a decision, note what hope the Hereafter inspires.","Whisper a dua asking for ease and accountability.","Notice if the balance nudges you toward courage."]}]},{"chapterId":15,"tracks":[{"id":"paradise-focus","title":"Paradise Focus","description":"Let paradise imagery guide your tiny deeds today.","steps":["Write down two deeds that inch you toward paradise.","Offer a dua asking for the strength to keep them steady.","Share a quick reflection with someone who inspires you."]},{"id":"paradise-balance","title":"Balance Reminders","description":"Carry a reminder that balances hope and awe about the next life.","steps":["Pick one warning and one hope from the chapter.","Write a dua that honors both feelings.","Let the dua shape a decision you\'ll protect today."]},{"id":"paradise-gratitude","title":"Gratitude Finish","description":"Close the day with gratitude, knowing each deed ripples into the afterlife.","steps":["List three blessings you feel in your heart as you read the chapter.","Send a dua of thanks for each blessing.","Keep one of the blessings as an intention to re-show in tomorrow\'s actions."]}]}]')}}]);